INSERT INTO `attraction_reviews` VALUES (7,'2026-06-23 12:54:50.592363','2026-06-23 12:54:50.592363','일출이 정말 장관이었어요! 새벽에 올라간 보람이 있네요.','126508001',5,12),(8,'2026-06-23 12:54:50.605297','2026-06-23 12:54:50.605297','한복 입고 입장하면 무료라 더 좋았어요.','126508',4,14),(9,'2026-06-23 12:54:50.611544','2026-06-23 12:54:50.611544','백사장이 넓고 야경이 환상적입니다.','126508003',5,13);
