INSERT INTO `hot_places` VALUES (2,'2026-06-23 11:30:44.659507','2026-06-23 11:30:44.659507','제주특별자치도 서귀포시 성산읍 일출로 284-12','NATURE','유네스코 세계자연유산. 일출 명소로 유명한 제주의 대표 관광지.',33.4581,126.9425,'성산일출봉','APPROVED',5,0),(3,'2026-06-23 11:30:44.861163','2026-06-23 11:30:44.861163','제주특별자치도 제주시 한림읍 협재리','NATURE','에메랄드빛 바다와 비양도 전망이 일품인 해변.',33.394,126.2396,'협재 해수욕장','APPROVED',5,0),(4,'2026-06-23 11:30:45.061047','2026-06-23 11:30:45.061047','제주특별자치도 서귀포시 안덕면 신화역사로 15','CAFE','녹차밭이 펼쳐진 카페 겸 박물관. 녹차 아이스크림이 인기.',33.3056,126.2895,'오설록 티 뮤지엄','APPROVED',5,0),(5,'2026-06-23 11:30:45.336695','2026-06-23 11:30:45.336695','제주특별자치도 제주시 건입동','RESTAURANT','제주 흑돼지 맛집이 모여있는 거리. 연탄구이가 별미.',33.5145,126.527,'흑돼지 거리','APPROVED',5,0),(7,'2026-06-23 12:54:51.214572','2026-06-23 12:54:51.289971','부산광역시 영도구 흰여울길','ATTRACTION','영화 촬영지로 유명한 바다 절벽 마을.',35.0789,129.0468,'흰여울문화마을','APPROVED',13,1240),(8,'2026-06-23 12:54:51.221174','2026-06-23 12:54:51.290287','제주특별자치도 서귀포시 성산읍 일출로','NATURE','유네스코 세계자연유산. 일출 명소.',33.4581,126.9425,'성산일출봉','APPROVED',12,1080),(9,'2026-06-23 12:54:51.225947','2026-06-23 12:54:51.290371','서울특별시 종로구 계동길','ATTRACTION','전통 한옥이 늘어선 골목.',37.5826,126.9831,'북촌한옥마을','APPROVED',14,870),(10,'2026-06-23 12:54:51.229888','2026-06-23 12:54:51.290424','제주특별자치도 제주시 한림읍 협재리','NATURE','에메랄드빛 바다와 비양도 전망.',33.394,126.2396,'협재해수욕장','APPROVED',12,760),(11,'2026-06-23 12:54:51.233375','2026-06-23 12:54:51.290482','부산광역시 사하구 감내2로','ATTRACTION','알록달록 산비탈 예술 마을.',35.0975,129.0107,'감천문화마을','APPROVED',13,640),(12,'2026-06-23 12:54:51.236247','2026-06-23 12:54:51.290531','서울특별시 종로구 창경궁로','RESTAURANT','빈대떡·마약김밥 등 길거리 먹거리.',37.5701,126.9999,'광장시장 먹자골목','APPROVED',15,520),(13,'2026-06-23 12:54:51.241672','2026-06-23 12:54:51.290799','서울특별시 용산구 남산공원길','ATTRACTION','서울 야경 1번지.',37.5512,126.9882,'남산서울타워','APPROVED',14,410),(14,'2026-06-23 12:54:51.246096','2026-06-23 12:54:51.291012','제주특별자치도 서귀포시 안덕면 신화역사로','CAFE','녹차밭 카페 겸 박물관.',33.3056,126.2895,'오설록 티 뮤지엄','APPROVED',12,280);
