INSERT INTO `posts` VALUES (3,'2026-06-23 11:30:45.513984','2026-06-23 11:56:41.674951','REVIEW','성산일출봉에서 일출 보고, 협재 해변 걷고, 오설록에서 녹차 아이스크림까지! 렌터카 없이 버스로도 충분히 다닐 수 있었어요. 추천 코스 공유합니다.',_binary '\0',0,'제주 2박 3일 뚜벅이 여행 후기 🌊',1,5),(4,'2026-06-23 11:30:45.713158','2026-06-23 11:30:45.713158','QUESTION','이번 주말에 제주 가는데 흑돼지 거리 어디가 제일 맛있나요? 연탄구이 잘하는 곳 아시는 분 댓글 부탁드려요 🙏',_binary '\0',0,'제주 흑돼지 맛집 추천해주세요!',0,5),(5,'2026-06-23 11:56:48.214027','2026-06-23 12:13:56.088393','REVIEW','dfdf',_binary '',0,'dfdf',6,5),(10,'2026-06-23 12:54:50.811583','2026-06-23 12:54:51.064603','RESTAURANT','현지인 추천 받아 다녀온 흑돼지 맛집들 정리해봤어요. 연탄구이는 진리!',_binary '\0',3,'제주 흑돼지 맛집 BEST 5 🐷',0,15),(11,'2026-06-23 12:54:50.817163','2026-06-23 12:54:51.122874','TIP','경복궁 야간개장 예매 꿀팁이랑 동선 정리. 미리 예매 필수예요!',_binary '\0',2,'서울 고궁 야간개장 일정 공유합니다',0,14),(12,'2026-06-23 12:54:50.821880','2026-06-23 12:54:51.176466','REVIEW','버스랑 도보로만 다녔는데 생각보다 충분했어요. 다닌 코스 공유합니다!',_binary '\0',3,'혼자 제주 2박3일 뚜벅이 후기',0,12),(13,'2026-06-23 12:54:50.824428','2026-06-23 12:54:51.203404','QUESTION','이번 주말 부산 가는데 야경 보기 좋은 곳 추천 부탁드려요 🙏',_binary '\0',1,'부산 야경 명소 어디가 제일 좋나요?',0,13);
