INSERT INTO `recommendations` VALUES (1,'2026-06-23 12:15:05.281248','2026-06-23 12:15:05.281248',NULL,NULL,32533,'gpt-4o-mini','4eb5d16828cb01f2bc972da1ecb226124c32a7583de7047c4b48c4698ed16d85','{\"budget\": 300000, \"themes\": [\"food\", \"sea\"], \"endDate\": \"2026-07-02\", \"areaCode\": \"1\", \"startDate\": \"2026-06-30\", \"companions\": \"COUPLE\"}','{\"days\": [{\"dayNo\": 1, \"places\": [{\"title\": \"중명전\", \"reason\": \"정동에 위치하여 역사적인 분위기를 느낄 수 있는 관광지입니다.\", \"contentId\": \"1017547\", \"visitTime\": \"10:00\"}, {\"title\": \"진옥화할매원조닭한마리\", \"reason\": \"전통적인 맛의 한식을 제공하는 음식점으로 점심에 적합합니다.\", \"contentId\": \"1325115\", \"visitTime\": \"12:30\"}, {\"title\": \"여의도한강공원\", \"reason\": \"한강 근처에 위치하여 여유롭게 산책할 수 있는 공원입니다.\", \"contentId\": \"1059479\", \"visitTime\": \"14:00\"}, {\"title\": \"신촌형제갈비\", \"reason\": \"저녁에 즐기기 좋은 고기 요리 전문점입니다.\", \"contentId\": \"132901\", \"visitTime\": \"18:00\"}], \"summary\": \"정동과 한강 주변의 역사적 명소와 맛집을 즐길 수 있는 일정입니다.\"}, {\"dayNo\": 2, \"places\": [{\"title\": \"와룡공원\", \"reason\": \"자연과 함께하는 공원으로 산책하기 좋은 장소입니다.\", \"contentId\": \"1019041\", \"visitTime\": \"10:00\"}, {\"title\": \"인사동찻집\", \"reason\": \"전통찻집으로, 점심으로 가볍게 즐기기 좋은 곳입니다.\", \"contentId\": \"1063403\", \"visitTime\": \"12:30\"}, {\"title\": \"양천구어린이교통안전교육장\", \"reason\": \"한강을 바라보며 여유를 즐길 수 있는 관광지입니다.\", \"contentId\": \"1105980\", \"visitTime\": \"14:00\"}, {\"title\": \"삼원가든\", \"reason\": \"저녁식사로 적합한 맛있는 한식 전문점입니다.\", \"contentId\": \"132892\", \"visitTime\": \"18:00\"}], \"summary\": \"자연과 문화를 함께 즐길 수 있는 일정으로 구성하였습니다.\"}, {\"dayNo\": 3, \"places\": [{\"title\": \"용금옥\", \"reason\": \"도심 속에서 바다를 느낄 수 있는 산책로입니다.\", \"contentId\": \"132820\", \"visitTime\": \"10:00\"}, {\"title\": \"신승관\", \"reason\": \"전통 한식 점심이 가능한 곳입니다.\", \"contentId\": \"1325623\", \"visitTime\": \"12:30\"}, {\"title\": \"봉화산근린공원\", \"reason\": \"도심 속에서 자연을 즐길 수 있는 공원입니다.\", \"contentId\": \"1115299\", \"visitTime\": \"14:00\"}, {\"title\": \"옛찻집\", \"reason\": \"전통적인 분위기의 찻집에서 저녁을 즐길 수 있습니다.\", \"contentId\": \"1063408\", \"visitTime\": \"18:00\"}], \"summary\": \"도심에서의 마지막 날로 자연과 전통을 함께 즐기는 일정입니다.\"}], \"totalSummary\": \"서울에서 바다와 해변을 느낄 수 있는 다양한 관광지와 맛집을 경험하는 3일 일정입니다.\"}',NULL,'SUCCESS',5),(2,'2026-06-23 12:52:36.043303','2026-06-23 12:52:45.767443',NULL,NULL,16445,'gpt-4o-mini','db7d73a484107249c540e7cf151a49c8ad6f9c5d93cfab51934d6ffcd9c120fc','{\"budget\": 300000, \"themes\": [\"activity\", \"food\", \"mountain\", \"sea\"], \"endDate\": \"2026-07-02\", \"areaCode\": \"7\", \"startDate\": \"2026-06-30\", \"companions\": \"COUPLE\"}','{\"days\": [{\"dayNo\": 1, \"places\": [{\"title\": \"일산해수욕장(울산)\", \"reason\": \"일산해수욕장에서 바다를 즐기며 여유로운 시간을 보낼 수 있습니다.\", \"contentId\": \"126091\", \"visitTime\": \"10:00\"}, {\"title\": \"고래고기원조할매집\", \"reason\": \"해변 근처의 고래고기 전문 맛집으로, 신선한 해산물을 맛볼 수 있습니다.\", \"contentId\": \"1019409\", \"visitTime\": \"12:30\"}, {\"title\": \"대왕암공원\", \"reason\": \"대왕암공원에서 아름다운 자연 경관을 감상하며 산책할 수 있습니다.\", \"contentId\": \"127515\", \"visitTime\": \"14:00\"}, {\"title\": \"산돼지마을\", \"reason\": \"자연 속에서 맛있는 고기를 구워 먹는 체험을 할 수 있습니다.\", \"contentId\": \"135898\", \"visitTime\": \"18:00\"}], \"summary\": \"일산해수욕장에서 바다를 즐기고, 고래고기 전문 맛집에서 식사 후 대왕암공원에서 자연을 만끽하는 일정입니다.\"}, {\"dayNo\": 2, \"places\": [{\"title\": \"국립 신불산폭포자연휴양림\", \"reason\": \"신불산폭포자연휴양림에서 자연 속에서 힐링할 수 있습니다.\", \"contentId\": \"125418\", \"visitTime\": \"09:00\"}, {\"title\": \"언양전통불고기\", \"reason\": \"언양전통불고기에서 전통적인 불고기를 맛볼 수 있습니다.\", \"contentId\": \"1019423\", \"visitTime\": \"12:00\"}, {\"title\": \"천전리각석계곡(울산)\", \"reason\": \"천전리각석계곡에서 물놀이와 산책을 즐길 수 있습니다.\", \"contentId\": \"126068\", \"visitTime\": \"14:00\"}, {\"title\": \"언양불고기 한마당한우촌\", \"reason\": \"언양불고기 한마당한우촌에서 더 맛있는 고기를 즐길 수 있습니다.\", \"contentId\": \"1325618\", \"visitTime\": \"17:30\"}], \"summary\": \"신불산에서 자연을 만끽하고, 언양의 전통 불고기를 맛본 후 계곡에서 여유로운 시간을 보냅니다.\"}, {\"dayNo\": 3, \"places\": [{\"title\": \"자수정 동굴나라\", \"reason\": \"자수정 동굴나라에서 신비로운 동굴 탐험을 할 수 있습니다.\", \"contentId\": \"126722\", \"visitTime\": \"10:00\"}, {\"title\": \"베네치아\", \"reason\": \"동굴 탐험 후 베네치아에서 이탈리안 음식을 즐길 수 있습니다.\", \"contentId\": \"1983747\", \"visitTime\": \"12:30\"}, {\"title\": \"간절곶\", \"reason\": \"간절곶에서 해돋이를 감상하며 로맨틱한 시간을 보낼 수 있습니다.\", \"contentId\": \"128022\", \"visitTime\": \"14:30\"}, {\"title\": \"정원숯불구이\", \"reason\": \"정원숯불구이에서 바비큐를 즐기며 여행의 마무리를 할 수 있습니다.\", \"contentId\": \"135899\", \"visitTime\": \"18:00\"}], \"summary\": \"신비로운 자수정 동굴 탐험 후 이탈리안 레스토랑에서 식사를 하고, 간절곶에서 해돋이를 감상하며 여행을 마무리합니다.\"}], \"totalSummary\": \"울산의 바다와 자연을 느끼며 맛있는 음식을 즐기는 3일간의 여행입니다.\"}',12,'SUCCESS',5);
